const body = $json.body || $json;
const messageText = String(body.Body || '').trim();
const fromNumber = String(body.From || '').replace('whatsapp:', '').trim();

const normalizedText = decodeURIComponent(messageText);
const qrMatch = normalizedText.match(/HOLA_MD[:](\d+)[:]([A-Za-z0-9_-]+)/i);

const clinicId = qrMatch ? Number(qrMatch[1]) : null;
const patientToken = qrMatch ? qrMatch[2] : null;

return [{
  json: {
    clinicId,
    patientToken,
    whatsappNumber: fromNumber,
    messageText,
    waMessageId: body.MessageSid || `MSG_${Date.now()}`,
    contactName: body.ProfileName || 'Patient'
  }
}];

const input = $('Parse Twilio Payload & QR Code').first()?.json || {};
const session = $('Session With Patient').first()?.json || {};
const availability = $json || {};
const slots = Array.isArray(availability.slots) ? availability.slots : [];
const message = String(input.messageText || '').trim();

function normalizeTime(value) {
  if (value === null || value === undefined) return null;
  const s = String(value).trim().toUpperCase().replace(/\s+/g, ' ');
  let m = s.match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);
  if (m) {
    const h = Number(m[1]);
    const min = Number(m[2]);
    if (h < 0 || h > 23 || min > 59) return null;
    return `${String(h).padStart(2, '0')}:${String(min).padStart(2, '0')}`;
  }
  m = s.match(/^(\d{1,2})(?::(\d{2}))?\s*(AM|PM)$/);
  if (m) {
    let h = Number(m[1]);
    const min = Number(m[2] || 0);
    const period = m[3];
    if (h < 1 || h > 12 || min > 59) return null;
    if (period === 'AM' && h === 12) h = 0;
    if (period === 'PM' && h !== 12) h += 12;
    return `${String(h).padStart(2, '0')}:${String(min).padStart(2, '0')}`;
  }
  m = s.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/);
  if (m) {
    const h = Number(m[1]);
    const min = Number(m[2]);
    if (h >= 0 && h <= 23 && min <= 59) {
      return `${String(h).padStart(2, '0')}:${String(min).padStart(2, '0')}`;
    }
  }
  return null;
}

function displayTime(hhmm) {
  const parts = String(hhmm).slice(0, 5).split(':').map(Number);
  const hRaw = parts[0];
  const mRaw = parts[1] || 0;
  const suffix = hRaw >= 12 ? 'PM' : 'AM';
  const hour = hRaw % 12 || 12;
  return `${hour}:${String(mRaw).padStart(2, '0')} ${suffix}`;
}

const uniqueSlots = [...new Set(slots.map(normalizeTime).filter(Boolean))];
const patientId = session.patientId || null;
const patientName = session.patientName || input.contactName || null;

if (uniqueSlots.length === 0) {
  return [{
    json: {
      kind: 'NO_SLOTS',
      selectedStartTime: null,
      shouldBook: false,
      patientId,
      patientName,
      reply_to_patient: `Sorry, there are no available slots on ${session.appointmentDate || 'the requested date'}. Would you like to choose another date?`,
      session_updates: {
        sessionId: session.sessionId,
        clinicId: session.clinicId,
        whatsappNumber: session.whatsappNumber,
        intent: session.intent ?? 'BOOK_APPOINTMENT',
        serviceId: session.serviceId ?? null,
        doctorId: session.doctorId ?? null,
        appointmentDate: session.appointmentDate ?? null,
        selectedStartTime: null,
        patientId,
        patientName,
        state: 'COLLECTING_DATE'
      }
    }
  }];
}

let selectedStartTime = null;
if (/^\d+$/.test(message)) {
  const n = Number(message);
  if (n >= 1 && n <= uniqueSlots.length) selectedStartTime = uniqueSlots[n - 1];
}
if (!selectedStartTime) {
  const normalizedMessage = normalizeTime(message);
  if (normalizedMessage && uniqueSlots.includes(normalizedMessage)) selectedStartTime = normalizedMessage;
}

if (!selectedStartTime) {
  return [{
    json: {
      kind: 'INVALID_SLOT',
      selectedStartTime: null,
      shouldBook: false,
      patientId,
      patientName,
      reply_to_patient: `Please choose one of the available slots:\n\n` + uniqueSlots.map((slot, i) => `${i + 1}. ${displayTime(slot)}`).join('\n'),
      session_updates: {
        sessionId: session.sessionId,
        clinicId: session.clinicId,
        whatsappNumber: session.whatsappNumber,
        intent: session.intent ?? 'BOOK_APPOINTMENT',
        serviceId: session.serviceId ?? null,
        doctorId: session.doctorId ?? null,
        appointmentDate: session.appointmentDate ?? null,
        selectedStartTime: null,
        patientId,
        patientName,
        state: 'WAITING_FOR_SLOT'
      },
      availableSlots: uniqueSlots
    }
  }];
}

return [{
  json: {
    kind: 'BOOK',
    selectedStartTime,
    patientId,
    patientName,
    shouldBook: true,
    reply_to_patient: `Great. I have selected ${displayTime(selectedStartTime)}. Proceeding with booking.`,
    session_updates: {
      sessionId: session.sessionId,
      clinicId: session.clinicId,
      whatsappNumber: session.whatsappNumber,
      intent: session.intent ?? 'BOOK_APPOINTMENT',
      serviceId: session.serviceId ?? null,
      doctorId: session.doctorId ?? null,
      appointmentDate: session.appointmentDate ?? null,
      selectedStartTime,
      patientId,
      patientName,
      state: 'READY_TO_BOOK'
    }
  }
}];

const r = $json || {};

const statusCode = Number(
  r.statusCode ??
  r.status ??
  0
);

const body =
  r.body && typeof r.body === 'object'
    ? r.body
    : r;

const success =
  (statusCode >= 200 && statusCode < 300) ||
  body?.appointmentId != null ||
  body?.id != null ||
  ["CONFIRMED", "BOOKED", "SUCCESS", "CREATED"]
    .includes(String(body?.status || body?.appointmentStatus || '').toUpperCase());

const conflict =
  statusCode === 409 ||
  String(body?.code || body?.errorCode || '').toUpperCase() === 'SLOT_UNAVAILABLE';

const appointmentId = body?.appointmentId ?? body?.id ?? null;
const s = $('Session With Patient').first().json;
const time = $('Handle Slot Selection').first().json.selectedStartTime;

return [{
  json: {
    success,
    conflict,
    statusCode,
    appointmentId,
    time,
    date: s.appointmentDate,
    reply_to_patient:
      success
        ? `Your appointment has been booked successfully for ${s.appointmentDate} at ${time}.${appointmentId ? ` Appointment ID: ${appointmentId}.` : ''}`
        : conflict
          ? `Sorry, the ${time} slot was just booked by another patient. Let me check the remaining slots.`
          : `Sorry, I could not book the appointment for ${s.appointmentDate} at ${time}. Please try again.`
  }
}];

const input=$('Parse Twilio Payload & QR Code').first()?.json || {}; const s=$('Session With Patient').first()?.json || {};
const name=String(input.messageText||'').trim();
return [{json:{patientName:name,session:s}}];

