const r = $json;
const text = r?.candidates?.[0]?.content?.parts?.[0]?.text || '';
let parsed;
try { parsed = JSON.parse(text); } catch (e) { parsed = { type: 'UNKNOWN', value: null, doctorId: null }; }
return [{ json: parsed }];

const ai = $('Parse AI').first()?.json || {};
const s = $('Session With Patient').first()?.json || {};
const input = $('Parse Twilio Payload & QR Code').first()?.json || {};
const message = String(input.messageText || '').trim();

let doctors = [];
try {
  doctors = $('Fetch Clinic Doctors').all().map(i => i.json);
} catch (e) {
  doctors = [];
}

const type = String(ai.type || 'UNKNOWN').toUpperCase();
const value = String(ai.value || '').trim();

let serviceId = s.serviceId ?? null;
let doctorId = s.doctorId ?? null;
let date = s.appointmentDate ?? null;
let state = s.state;
let reply = '';
let action = 'NONE';

function matchDoctor(val) {
  if (val === null || val === undefined || val === '') return null;
  const m = String(val).toLowerCase().replace(/^dr\.?\s+/, '').trim();
  if (/^\d+$/.test(m)) {
    const n = Number(m);
    if (n >= 1 && n <= doctors.length) return doctors[n - 1];
  }
  const byId = doctors.find(x => String(x.id) === String(val));
  if (byId) return byId;
  return doctors.find(x => String(x.name || '').toLowerCase().replace(/^dr\.?\s+/, '').trim() === m)
    || doctors.find(x => String(x.name || '').toLowerCase().includes(m));
}

function applyDoctor(match) {
  doctorId = match.id;
  serviceId = match.serviceId || match.defaultServiceId || serviceId;
  date = null;
  state = 'COLLECTING_DATE';
  reply = `Great! You've selected ${match.name}. What date would you like? (e.g., 2026-09-15)`;
}

/** Parse many common date formats to YYYY-MM-DD */
function parseDate(text) {
  if (!text) return null;
  const t = String(text).trim();

  // YYYY-MM-DD or YYYY/MM/DD
  let m = t.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})$/);
  if (m) {
    const y = m[1], mo = String(m[2]).padStart(2, '0'), d = String(m[3]).padStart(2, '0');
    return `${y}-${mo}-${d}`;
  }

  // DD-MM-YYYY or DD/MM/YYYY or DD.MM.YYYY
  m = t.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{4})$/);
  if (m) {
    const d = String(m[1]).padStart(2, '0'), mo = String(m[2]).padStart(2, '0'), y = m[3];
    return `${y}-${mo}-${d}`;
  }

  // DD-MM-YY
  m = t.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{2})$/);
  if (m) {
    const d = String(m[1]).padStart(2, '0'), mo = String(m[2]).padStart(2, '0');
    let y = Number(m[3]);
    y = y < 50 ? 2000 + y : 1900 + y;
    return `${y}-${mo}-${d}`;
  }

  return null;
}

const parsedFromMessage = parseDate(message);
const parsedFromAi = parseDate(value) || (type === 'DATE' && /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : null);
const resolvedDate = parsedFromMessage || parsedFromAi;

// --- COLLECTING_DATE (or already have doctor): accept date and show slots ---
if (s.state === 'COLLECTING_DATE' || (s.doctorId && resolvedDate)) {
  if (resolvedDate) {
    date = resolvedDate;
    doctorId = doctorId || s.doctorId;
    serviceId = serviceId || s.serviceId;
    state = 'WAITING_FOR_SLOT';
    action = 'CHECK_AVAILABILITY';
    reply = `Thank you. Checking available slots for ${date}.`;
  } else if (type === 'DOCTOR') {
    const match = matchDoctor(ai.doctorId) || matchDoctor(value);
    if (match) applyDoctor(match);
    else {
      state = 'COLLECTING_DATE';
      reply = 'Please provide the appointment date, for example 2026-09-15.';
    }
  } else {
    state = 'COLLECTING_DATE';
    reply = 'Please provide the appointment date, for example 2026-09-15.';
  }
} else {
  // STARTED / COLLECTING_DOCTOR / no doctor yet
  const match = matchDoctor(ai.doctorId) || matchDoctor(value);
  if (match) {
    applyDoctor(match);
  } else if (resolvedDate && doctors.length === 1) {
    applyDoctor(doctors[0]);
    date = resolvedDate;
    state = 'WAITING_FOR_SLOT';
    action = 'CHECK_AVAILABILITY';
    reply = `Thank you. Checking available slots for ${date}.`;
  } else if (resolvedDate && s.doctorId) {
    date = resolvedDate;
    state = 'WAITING_FOR_SLOT';
    action = 'CHECK_AVAILABILITY';
    reply = `Thank you. Checking available slots for ${date}.`;
  } else {
    state = 'COLLECTING_DOCTOR';
    reply = doctors.length
      ? `Please choose a doctor:\n\n${doctors.map((x, i) => `${i + 1}. ${x.name}`).join('\n')}`
      : `Sorry, no doctors are available right now. Please try again later.`;
  }
}

return [{ json: { serviceId, doctorId, appointmentDate: date, state, action, reply_to_patient: reply } }];

const a = $json || {};
const slots = Array.isArray(a.slots) ? a.slots : [];
const date = a.date || $('Process AI Selection').first()?.json?.appointmentDate;
const fmt = (v) => {
  const [h, m] = String(v).split(':').map(Number);
  return `${h % 12 || 12}:${String(m || 0).padStart(2, '0')} ${h >= 12 ? 'PM' : 'AM'}`;
};
const reply = slots.length
  ? `Available slots for ${date}:\n\n${slots.map((s, i) => `${i + 1}. ${fmt(s)}`).join('\n')}\n\nReply with the number or time of your preferred slot.`
  : `Sorry, there are no available slots on ${date}. Would you like another date?`;
return [{
  json: {
    slots,
    date,
    reply_to_patient: reply,
    state: slots.length ? 'WAITING_FOR_SLOT' : 'COLLECTING_DATE'
  }
}];

const a = $json || {};
const slots = Array.isArray(a.slots) ? a.slots : [];
const session = $('Session With Patient').first().json || {};
const date = a.date || session.appointmentDate;

function normalizeTime(value) {
  const s = String(value ?? '').trim().toUpperCase();
  let m = s.match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);

  if (m) {
    const h = Number(m[1]);
    const min = Number(m[2]);
    if (h < 0 || h > 23 || min > 59) return null;
    return `${String(h).padStart(2, '0')}:${String(min).padStart(2, '0')}`;
  }

  m = s.match(/^(\d{1,2})(?::(\d{2}))?\s*(AM|PM)$/);

  if (m) {
    let h = Number(m[1]);
    const min = Number(m[2] || 0);
    const period = m[3];

    if (h < 1 || h > 12 || min > 59) return null;

    if (period === 'AM' && h === 12) h = 0;
    if (period === 'PM' && h !== 12) h += 12;

    return `${String(h).padStart(2, '0')}:${String(min).padStart(2, '0')}`;
  }

  return null;
}

function displayTime(hhmm) {
  const [h, m] = hhmm.split(':').map(Number);
  return `${h % 12 || 12}:${String(m).padStart(2, '0')} ${h >= 12 ? 'PM' : 'AM'}`;
}

const uniqueSlots = [...new Set(slots.map(normalizeTime).filter(Boolean))];

if (uniqueSlots.length === 0) {
  return [{
    json: {
      conflictResult: "NO_SLOTS",
      state: "COLLECTING_DATE",
      selectedStartTime: null,
      reply_to_patient:
        `Sorry, the selected slot was just booked by another patient, and there are no other available slots on ${date}. ` +
        `Please choose another date.`
    }
  }];
}

return [{
  json: {
    conflictResult: "SLOTS_REMAIN",
    state: "WAITING_FOR_SLOT",
    selectedStartTime: null,
    availableSlots: uniqueSlots,
    reply_to_patient:
      `Sorry, the selected slot was just booked by another patient.\n\n` +
      `Remaining available slots for ${date}:\n\n` +
      uniqueSlots.map((slot, i) => `${i + 1}. ${displayTime(slot)}`).join('\n') +
      `\n\nPlease choose another slot.`
  }
}];

const docs = $('Fetch Clinic Doctors').all().map(i => i.json);
const autoDoctor = docs[0] || {};
const session = $('Session With Patient').first()?.json || {};
const patientName = session.patientName || $('Parse Twilio Payload & QR Code').first()?.json?.contactName || 'Patient';
const serviceId = autoDoctor.serviceId || autoDoctor.defaultServiceId || session.serviceId || null;
return [{
  json: {
    doctorId: autoDoctor.id,
    doctorName: autoDoctor.name,
    serviceId,
    state: 'COLLECTING_DATE',
    reply_to_patient: `Hello ${patientName}! Welcome. You are booking with ${autoDoctor.name || 'our doctor'}. Please enter your preferred appointment date (e.g., 2026-09-15).`
  }
}];

const input = $('Parse Twilio Payload & QR Code').first()?.json || {};
const session = $('Session With Patient').first()?.json || {};
const message = String(input.messageText || '').trim();

function parseDate(text) {
  if (!text) return null;
  const t = String(text).trim();
  let m = t.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})$/);
  if (m) {
    return `${m[1]}-${String(m[2]).padStart(2,'0')}-${String(m[3]).padStart(2,'0')}`;
  }
  m = t.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{4})$/);
  if (m) {
    return `${m[3]}-${String(m[2]).padStart(2,'0')}-${String(m[1]).padStart(2,'0')}`;
  }
  m = t.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{2})$/);
  if (m) {
    let y = Number(m[3]);
    y = y < 50 ? 2000 + y : 1900 + y;
    return `${y}-${String(m[2]).padStart(2,'0')}-${String(m[1]).padStart(2,'0')}`;
  }
  return null;
}

const date = parseDate(message);
const isDate = !!date;
return [{
  json: {
    isDate,
    appointmentDate: date,
    doctorId: session.doctorId || null,
    serviceId: session.serviceId || null,
    clinicId: session.clinicId || null,
    sessionId: session.sessionId || null,
    state: isDate ? 'WAITING_FOR_SLOT' : session.state,
    action: isDate ? 'CHECK_AVAILABILITY' : 'NEED_AI'
  }
}];

const d = $('Try Parse Date Directly').first()?.json || {};
const s = $('Session With Patient').first()?.json || {};
return [{
  json: {
    serviceId: d.serviceId || s.serviceId || null,
    doctorId: d.doctorId || s.doctorId || null,
    appointmentDate: d.appointmentDate,
    state: 'WAITING_FOR_SLOT',
    action: 'CHECK_AVAILABILITY',
    reply_to_patient: `Thank you. Checking available slots for ${d.appointmentDate}.`
  }
}];

const a = $json || {};
const slots = Array.isArray(a.slots) ? a.slots : [];
const date = a.date || $('Merge Service Direct').first()?.json?.appointmentDate || $('Shape Direct Date Selection').first()?.json?.appointmentDate;
const fmt = (v) => {
  const [h, m] = String(v).split(':').map(Number);
  return `${h % 12 || 12}:${String(m || 0).padStart(2, '0')} ${h >= 12 ? 'PM' : 'AM'}`;
};
const reply = slots.length
  ? `Available slots for ${date}:\n\n${slots.map((s, i) => `${i + 1}. ${fmt(s)}`).join('\n')}\n\nReply with the number or time of your preferred slot.`
  : `Sorry, there are no available slots on ${date}. Would you like another date?`;
return [{
  json: {
    slots,
    date,
    reply_to_patient: reply,
    state: slots.length ? 'WAITING_FOR_SLOT' : 'COLLECTING_DATE'
  }
}];

const shape = $('Shape Direct Date Selection').first()?.json || {};
const session = $('Session With Patient').first()?.json || {};
const svc = $json || {};
const serviceId = svc.id || svc.serviceId || shape.serviceId || session.serviceId || null;
return [{
  json: {
    ...shape,
    serviceId,
    serviceName: svc.name || null,
    doctorId: shape.doctorId || session.doctorId || null,
    appointmentDate: shape.appointmentDate,
    state: 'WAITING_FOR_SLOT',
    action: 'CHECK_AVAILABILITY',
    reply_to_patient: shape.reply_to_patient || `Thank you. Checking available slots for ${shape.appointmentDate}.`
  }
}];

const sel = $('Process AI Selection').first()?.json || {};
const session = $('Session With Patient').first()?.json || {};
const svc = $json || {};
const serviceId = svc.id || svc.serviceId || sel.serviceId || session.serviceId || null;
return [{
  json: {
    ...sel,
    serviceId,
    serviceName: svc.name || null,
    doctorId: sel.doctorId || session.doctorId || null,
    appointmentDate: sel.appointmentDate,
    state: sel.state || 'WAITING_FOR_SLOT',
    action: sel.action || 'CHECK_AVAILABILITY',
    reply_to_patient: sel.reply_to_patient
  }
}];

const auto = $('Auto Select Single Doctor').first()?.json || {};
const svc = $json || {};
const serviceId = svc.id || svc.serviceId || auto.serviceId || null;
return [{
  json: {
    ...auto,
    serviceId,
    serviceName: svc.name || null
  }
}];

const identified = $json || {};
const parsed = $('Parse Twilio Payload & QR Code').first()?.json || {};
const patientId = identified.id ?? identified.patientId ?? identified.patient_id ?? null;
const patientName = identified.patientName || identified.name || identified.fullName || parsed.contactName || null;
return [{
  json: {
    patientId: patientId != null ? Number(patientId) : null,
    patientName,
    clinicId: parsed.clinicId != null ? Number(parsed.clinicId) : null,
    whatsappNumber: parsed.whatsappNumber,
    patientToken: parsed.patientToken
  }
}];

const session = $json || {};
let patientId = session.patientId || null;
let patientName = session.patientName || null;

try {
  const idn = $('Normalize Identified Patient').first();
  if (idn && idn.json) {
    patientId = patientId || idn.json.patientId || null;
    patientName = patientName || idn.json.patientName || null;
  }
} catch (e) {}

const sessionId = session.sessionId || session.id || null;
const noSession = !sessionId || session.code === 'NOT_FOUND' ||
  (typeof session.message === 'string' && session.message.toLowerCase().includes('no active session'));

if (noSession) {
  return [{
    json: {
      error: true,
      noSession: true,
      patientId,
      patientName,
      reply_to_patient: 'Please scan the clinic QR code to start booking an appointment.'
    }
  }];
}

return [{
  json: {
    ...session,
    sessionId,
    patientId,
    patientName,
    error: false,
    noSession: false
  }
}];

// Prefer current input (QR path already merged), else Attach Patient Id path
const fromInput = $json || {};
let session = fromInput;

if (!fromInput.sessionId) {
  try {
    const attached = $('Attach Patient Id If Present').first();
    if (attached && attached.json && attached.json.sessionId) {
      session = attached.json;
    }
  } catch (e) {}
}

return [{ json: session }];

const session = $json || {};
const identified = $('Normalize Identified Patient').first()?.json || {};

// Backend 404 body may look like { code, message } without sessionId
const hasSession = session.sessionId != null || session.id != null;
const sessionId = session.sessionId || session.id || null;
const patientId = session.patientId || identified.patientId || null;
const patientName = session.patientName || identified.patientName || null;
const clinicId = session.clinicId || identified.clinicId || null;

if (!hasSession) {
  return [{
    json: {
      error: true,
      message: session.message || 'Failed to create session',
      patientId,
      patientName,
      clinicId,
      whatsappNumber: identified.whatsappNumber,
      reply_to_patient: 'Sorry, I could not start your booking session. Please scan the QR code again.'
    }
  }];
}

return [{
  json: {
    ...session,
    sessionId,
    patientId,
    patientName,
    clinicId,
    whatsappNumber: session.whatsappNumber || identified.whatsappNumber,
    state: session.state || 'STARTED',
    intent: session.intent || 'BOOK_APPOINTMENT',
    error: false
  }
}];
